fn eval(f:&F,p:&P,x:&N)->N{p.iter().rev().fold(n(0),|v,c|f.add(&f.mul(&v,x),c))}
fn monic(f:&F,p:P)->P{if p.is_empty(){return p;}let inv=f.inv(p.last().unwrap());trim(p.iter().map(|x|f.mul(x,&inv)).collect())}
fn gcd(f:&F,mut a:P,mut b:P)->P{while !b.is_empty(){let r=f.rem(a,&b,false);a=b;b=r;}monic(f,a)}
fn div(f:&F,mut a:P,b:&P)->(P,P){assert!(!b.is_empty());if a.len()<b.len(){return(vec![],a);}let mut q=vec![n(0);a.len()-b.len()+1];let inv=f.inv(b.last().unwrap());while !a.is_empty()&&a.len()>=b.len(){let j=a.len()-b.len();let c=f.mul(a.last().unwrap(),&inv);q[j]=f.add(&q[j],&c);for(i,x)in b.iter().enumerate(){a[i+j]=f.sub(&a[i+j],&f.mul(&c,x));}a=trim(a);} (trim(q),a)}
fn subp(f:&F,mut a:P,b:&P)->P{a.resize(a.len().max(b.len()),n(0));for(i,x)in b.iter().enumerate(){a[i]=f.sub(&a[i],x);}trim(a)}
fn power(f:&F,mut a:P,h:&P,mut e:N)->P{let mut r=vec![n(1)];a=f.rem(a,h,false);while !e.is_zero(){if e.bit(0){r=f.rem(f.mulp(&r,&a),h,false);}e>>=1;if !e.is_zero(){a=f.rem(f.mulp(&a,&a),h,false);}}r}
fn random(f:&F,rng:&mut u64)->N{let q=f.order();let mut x=n(0);for _ in 0..q.bits().div_ceil(64){*rng^=*rng<<13;*rng^=*rng>>7;*rng^=*rng<<17;x=(x<<64)+N::from(*rng);}x%q}
fn split(f:&F,g:P,rng:&mut u64)->Option<Vec<N>>{if g.len()<=1{return Some(vec![]);}if g.len()==2{return Some(vec![f.neg(&g[0])]);}for _ in 0..64{let a=(0..g.len()-1).map(|_|random(f,rng)).collect::<P>();let b=subp(f,power(f,a,&g,(f.order()-n(1))>>1),&vec![n(1)]);let d=gcd(f,g.clone(),b);if d.len()>1&&d.len()<g.len(){let(q,r)=div(f,g.clone(),&d);assert!(r.is_empty());let mut left=split(f,d,rng)?;left.extend(split(f,q,rng)?);return Some(left);}}None}
fn roots(f:&F,h:&P,interval_bits:usize)->Option<(Vec<(N,usize)>,P,Vec<(N,usize)>)>{assert!(!matches!(f.k,Kind::Binary(..)));assert_eq!(h.last(),Some(&n(1)));let xp=power(f,vec![n(0),n(1)],h,f.order());let g=gcd(f,h.clone(),subp(f,xp,&vec![n(0),n(1)]));let mut rng=202610171123u64;let mut rs=split(f,g.clone(),&mut rng)?;rs.sort();assert!(!rs.windows(2).any(|x|x[0]==x[1]));assert_eq!(f.product(&rs),g);let mut out=vec![];let mut all=vec![];for x in rs{assert!(eval(f,h,&x).is_zero());let mut current=h.clone();let mut m=0;loop{let(q,r)=div(f,current.clone(),&vec![f.neg(&x),n(1)]);if !r.is_empty(){break;}current=q;m+=1;}assert!(m>0);all.push((x.clone(),m));if x<(N::one()<<interval_bits){out.push((x,m));}}Some((out,g,all))}
fn choose(i:usize,k:usize)->usize{let mut z=1;for j in 0..k{z=z*(i-j)/(j+1);}z}
fn brute(f:&F,h:&P,bits:usize)->Vec<(N,usize)>{(0..f.order().to_usize().unwrap()).map(N::from).filter(|x|*x<(N::one()<<bits)&&eval(f,h,x).is_zero()).map(|x|{let m=(1..h.len()).find(|k|{let d=trim((*k..h.len()).map(|i|f.mul(&f.scalar(choose(i,*k)),&h[i])).collect());!eval(f,&d,&x).is_zero()}).unwrap();(x,m)}).collect()}
